const releaseRawBlobs = `-- name: ReleaseRawBlobs :exec
UPDATE blobs b SET refcount = b.refcount - c.n
FROM (SELECT content_sha256, count(*)::integer AS n FROM raw_payloads WHERE id = ANY($1::bigint[]) GROUP BY content_sha256) c
WHERE b.sha256 = c.content_sha256
`

// One blob reference per raw row goes away (hold blob.LockShared); the sweeper removes the files.
func (q *Queries) ReleaseRawBlobs(ctx context.Context, ids []int64) error {
	_, err := q.db.Exec(ctx, releaseRawBlobs, ids)
	return err
}

const releaseUserBlobs = `-- name: ReleaseUserBlobs :exec
UPDATE blobs b SET refcount = b.refcount - c.n
FROM (
  SELECT sha256, count(*)::integer AS n FROM (
    SELECT rp.content_sha256 AS sha256 FROM raw_payloads rp WHERE rp.user_id = $1::uuid
    UNION ALL SELECT d.blob_sha256 FROM documents d WHERE d.user_id = $1::uuid AND d.blob_sha256 IS NOT NULL
    UNION ALL SELECT x.response_blob_sha256 FROM extraction_runs x WHERE x.user_id = $1::uuid AND x.response_blob_sha256 IS NOT NULL
    UNION ALL SELECT e.blob_sha256 FROM exports e WHERE e.user_id = $1::uuid AND e.blob_sha256 IS NOT NULL
  ) refs GROUP BY refs.sha256
) c
WHERE b.sha256 = c.sha256
`

// Drops the blob references of the owner's raw payloads, documents, extraction responses and
// exports (hold blob.LockShared); the sweeper removes the files.
func (q *Queries) ReleaseUserBlobs(ctx context.Context, userID uuid.UUID) error {
	_, err := q.db.Exec(ctx, releaseUserBlobs, userID)
	return err
}
